$fatpacked{"Utility.pm"} = '#line '.(1+__LINE__).' "'.__FILE__."\"\n".<<'UTILITY';
  use GitHub::Actions;
  use v5.36;
  
  # Imprime cabeceras de objetivo/hito, principalmente
  sub doing {
    my $what = shift;
    start_group "\t✔ Comprobando $what\n";
  }
  
  # Cuando los tests van bien
  sub all_good {
    return "✅🍊️‍🔥 " . shift
  }
  
  
  # Cuando fallan
  sub sorry {
    return "🍋💥❌ " . shift
  }
  
  sub comprueba_con_mensaje {
    my ( $expresion, $bien, $mal ) = @_;
    if ( $expresion ) {
      say all_good($bien);
    } else {
      error( sorry( $mal ) );
    }
  }
  
  sub README_contiene_con_mensaje {
    my ($cadena, $README) = @_;
    if (  $README =~ m/$cadena/i  ) {
      say all_good("El README contiene «$cadena»");
    } else {
      error( sorry("El README no contiene «$cadena».\nPor favor, consulta el guión del objetivo para ver por qué es necesario."));
    }
  }
  
  sub README_no_contiene_con_mensaje( $cadena, $README)  {
    if ( index( $README, $cadena ) < 0 ) {
      say all_good("El README no contiene «$cadena»");
    } else {
      error( sorry("El README no debe contener «$cadena». Consulta el guión del objetivo para ver por qué esto es un error") );
    }
  }
  
  # Cuando hay una advertencia, no bloqueante
  sub advierte {
    return "⚠️🍋 " . shift
  }
  
  # Convierte una lista de hallazgos (mensajes ya redactados) en avisos de
  # GitHub Actions. Si la lista está vacía se informa de que la comprobación
  # ha ido bien, en vez de quedarse en silencio.
  # $tipo vale 'error' (falla la Action) o 'warning' (no bloquea la entrega).
  sub informa_hallazgos {
    my ( $tipo, $mensaje_ok, @hallazgos ) = @_;
    if ( @hallazgos ) {
      for my $hallazgo (@hallazgos) {
        if ( $tipo eq 'error' ) {
          error( sorry( $hallazgo ) );
        } else {
          warning( advierte( $hallazgo ) );
        }
      }
    } else {
      say all_good( $mensaje_ok );
    }
  }
  
  sub groupify( $wrapped_function, $group_name ) {
    return sub {
      doing( $group_name );
      $wrapped_function->( @_ );
      end_group();
    }
  }
  
  sub comprueba_caps {
    my $nombre_fichero = shift;
    my $contexto = shift;
    my @files = (ref($nombre_fichero) eq 'ARRAY')?@$nombre_fichero:($nombre_fichero);
    for my $file (@files) {
      if ( $file =~ /[A-Z]/ ) {
        error (sorry( "⚠ En $contexto, «$file» tiene mayúsculas, no es una buena práctica en repos ⚠" ));
      }
    }
  }
  
  sub file_present {
    my ($file, $ls_files_ref, $name ) = @_;
    my @files = (ref($file) eq 'ARRAY')?@$file:($file);
    say all_good("Buscando @files en @$ls_files_ref");
    for my $a_file (@files ) {
      comprueba_con_mensaje(  grep( /$a_file/, @$ls_files_ref ),
                 "Fichero $name → $a_file presente",
                 "Fichero $name → $a_file no está presente" );
    }
  
  }
  
  sub clave_presente {
    my $iv = shift;
    my $clave = shift;
    comprueba_con_mensaje( $iv->{$clave}, "🗝️ «$clave» presente", "Falta clave «$clave»" );
  }
  
  "Yay"
UTILITY

s/^  //mg for values %fatpacked;

my $class = 'FatPacked::'.(0+\%fatpacked);
no strict 'refs';
*{"${class}::files"} = sub { keys %{$_[0]} };

if ($] < 5.008) {
  *{"${class}::INC"} = sub {
    if (my $fat = $_[0]{$_[1]}) {
      my $pos = 0;
      my $last = length $fat;
      return (sub {
        return 0 if $pos == $last;
        my $next = (1 + index $fat, "\n", $pos) || $last;
        $_ .= substr $fat, $pos, $next - $pos;
        $pos = $next;
        return 1;
      });
    }
  };
}

else {
  *{"${class}::INC"} = sub {
    if (my $fat = $_[0]{$_[1]}) {
      open my $fh, '<', \$fat
        or die "FatPacker error loading $_[1] (could be a perl installation issue?)";
      return $fh;
    }
    return;
  };
}

unshift @INC, bless \%fatpacked, $class;
  } # END OF FATPACK CODE


use strict;
use warnings;
use v5.14;

use Git;
use GitHub::Actions;

use YAML qw(LoadFile);

use lib "lib";

use Utility;
use Objetivos;

my $fase = $ENV{'objetivo'};
my $config_file = $ENV{'CONFIGFILE'};

# Comenzando
groupify( sub { say "Objetivo $fase" }, "Metadatos" )->();

# Previa
my $student_repo = Git->repository ( Directory => "." );

# Algunas variables previas al objetivo 0
my @repo_files = $student_repo->command("ls-files");
my $README = pre_objetivo_0(\@repo_files);

groupify( \&objetivo_0, "Objetivo 0" )->(\@repo_files, $README);

exit_action() if $fase <= 1;

# Fase 2
my $iv;

my $file = "$config_file.yaml";
file_present( $file, \@repo_files, "Fichero metadatos" );
eval { $iv = LoadFile($file); };
if ($@) {
  set_failed( sorry( "Hay algún problema leyendo «$file» ⤷ $@" ) );
} else {
  say all_good( "Fichero de configuración ⚙ «$file» encontrado" );
}
$iv->{'CONFIGFILE'} = $file;

objetivo_2( $iv, \@repo_files );

exit_action() if $fase < 3;

objetivo_3( $iv, $README, \@repo_files );

exit_action() if $fase < 4;

objetivo_4( $iv, $README, \@repo_files );

exit_action() if $fase < 5;

if ( -f "DOCKER_USER" ) {
  say "❢ Usuario de Docker alternativo";
  open( my $fh, "<", "DOCKER_USER" ) || die "No puedo abrir DOCKER_USER";
  my $docker_user = <$fh>;
  chomp $docker_user;
  set_env( 'docker_user', $docker_user );
} else {
  set_env( 'docker_user', $ENV{'user'} );
}

objetivo_5( $iv,  \@repo_files );

exit_action() if $fase < 6;

objetivo_6( $iv,  \@repo_files );

exit_action() if $fase < 7;

objetivo_7( $iv,  \@repo_files );

exit_action() if $fase < 8;

objetivo_8( $iv);

exit_action();

